FAMILIES = [{'id': 'fin_fam_00', 'name': 'upi_collect_request', 'style': 'first_person_complaint', 'narratives': ['Yesterday while attempting to sell home furniture online, a buyer called claiming they could only pay via phone UPI. The caller sent a collect request on Google Pay for 25,000 rupees and instructed me to scan a QR code and enter my UPI PIN to accept payment. The caller insisted that entering the PIN was standard verification to receive funds into my bank account. Instead of receiving payment, 25,000 rupees was debited from my account.', 'An unauthorized debit of 32,000 rupees occurred on my PhonePe account after an individual sent a payment link claiming to be an army officer purchasing my used laptop. The individual assured me that clicking approve and confirming my six-digit UPI security PIN was mandatory to accept defense department funds. Believing the explanation, I authorized the prompt and saw my savings account debited immediately.', 'Filing a complaint regarding a UPI collect request fraud. A buyer claiming to represent an educational institution called to purchase textbooks. They sent a payment collect notification of 18,000 rupees via Paytm and instructed me to confirm transaction security by typing my secret PIN. Seconds after entering the PIN, the amount was transferred out of my bank balance to an unverified beneficiary handle.', 'I was defrauded of 45,000 rupees through a fraudulent QR code transaction. A scammer posing as a prospective tenant asked to pay rental deposit money via UPI. They sent a QR code through WhatsApp and instructed me to scan it through my banking app and enter my security PIN. The action initiated an instant fund transfer to an unknown bank account.', 'A caller claiming to represent customer care sent an automated collect request of 28,000 rupees to my UPI handle. They claimed this was a mandatory verification step to reverse an earlier failed transaction. Upon entering my UPI PIN as instructed, the transaction completed as a debit rather than a refund.', 'I received a collect request of 35,000 rupees on my BHIM application from an unknown party claiming to be an online marketplace buyer. The buyer guided me over the phone to enter my authorization PIN to receive advance booking money. The funds were instantly debited from my linked bank account.', 'An unauthorized transfer of 50,000 rupees occurred when a caller claiming to buy my television sent a payment barcode. The caller stated that scanning the code and entering my secret PIN would credit my account. Immediately after entering my PIN, an SMS confirmed the debit of funds.', 'A fraudster claiming to be an official buyer sent two separate collect requests of 15,000 rupees each. They claimed that my UPI daily limit required dual verification by entering my MPIN. Both requests resulted in immediate debits totaling 30,000 rupees.', 'I was deceived into authorizing a payment collect notification on Google Pay. The sender claimed to be sending a cash prize and instructed me to confirm receipt with my UPI PIN. My savings account was debited for 22,000 rupees instead.', 'A scammer claiming to buy musical equipment sent a collect prompt of 40,000 rupees. They insisted that entering my PIN on PhonePe was necessary to receive payment. After following the instructions, my balance was reduced by 40,000 rupees.', 'A fraudulent buyer sent a payment request on my banking UPI app. They persuaded me to approve the transaction with my secret PIN to receive an advance deposit, resulting in an unauthorized deduction of 38,000 rupees.', 'An online caller guided me through a supposed payment receiving process via a QR code. Entering my UPI PIN authorized an instant withdrawal of 27,000 rupees from my State Bank account to an unknown recipient.'], 'concise': ['Scammer sent a UPI collect request claiming to pay advance money, stealing 25000 rupees upon PIN entry.', 'Tricked into scanning a QR code and entering UPI security PIN which debited 32000 rupees from my bank.', 'Fraudulent buyer sent collect request on PhonePe, falsely claiming PIN was needed to receive payment.']}, {'id': 'fin_fam_01', 'name': 'atm_skimming_cloning', 'style': 'first_person_complaint', 'narratives': ['My debit card was cloned after I withdrew cash from an off-site automated teller machine in Bangalore. Two days later, while my physical card remained securely in my possession, multiple unauthorized ATM cash withdrawals occurred in Delhi totaling 50,000 rupees. The bank branch confirmed that a magnetic stripe skimmer and hidden pinhole camera had been detected at the ATM terminal I visited.', 'Filing a cyber complaint regarding card cloning and fraudulent ATM withdrawals. Unauthorized cash debits of 40,000 rupees occurred at 2:00 AM from an ATM location 800 kilometers away from my residence. My physical debit card was never misplaced, indicating that criminals duplicated the magnetic stripe data and captured my PIN during a previous transaction.', 'I received three consecutive SMS alerts from my bank informing me of cash withdrawals totaling 60,000 rupees from an automated teller machine. I was asleep at the time with my debit card in my wallet. The bank security team suspects a card skimming device at a roadside cash dispenser captured my credentials.', 'An unauthorized withdrawal of 35,000 rupees was debited from my savings account via an ATM terminal in another state. Since my debit card was in my wallet throughout the day, the card data and security PIN were evidently skimmed and encoded onto a duplicate plastic card by criminals.', 'My salary account was drained of 48,000 rupees through four sequential ATM transactions within fifteen minutes. I possess my original debit card and never shared my PIN. The bank informed me that fraudulent cloned cards were used at an unmonitored cash machine.', 'I am reporting an unauthorized ATM transaction of 25,000 rupees. The debit occurred at a midnight hour while my physical debit card was locked in my drawer. The card details were apparently cloned using a skimming device at an ATM vestibule.', 'Multiple unauthorized cash withdrawals totaling 55,000 rupees took place on my debit card without my knowledge. The transactions originated from an automated teller machine in a distant city, confirming that magnetic card cloning occurred.', 'A total of 42,000 rupees was withdrawn from my account at an off-site cash dispenser. I hold my debit card and never disclosed my ATM PIN. Criminals cloned the magnetic data to produce a counterfeit card for the transaction.', 'My bank alerted me to consecutive ATM cash deductions totaling 30,000 rupees. The physical card was never out of my control, indicating that my card credentials were stolen through an ATM skimmer.', 'Unauthorized cash dispensations amounting to 52,000 rupees occurred on my bank account overnight. The physical debit card was in my custody, confirming that card cloning was used to execute the theft.', 'Criminals used a cloned debit card to withdraw 38,000 rupees from my savings account across three automated cash machines while my original card was with me.', 'An unauthorized cash withdrawal of 45,000 rupees took place using counterfeit cloned card media following an ATM skimming incident at an unmonitored kiosk.'], 'concise': ['Debit card was cloned at an ATM skimming terminal, leading to 50000 rupees in unauthorized cash withdrawals.', 'Physical card remained in my wallet while unauthorized ATM debits totaling 40000 rupees drained my account.', 'Skimming device captured magnetic card data and PIN, enabling criminals to withdraw cash using a cloned card.']}, {'id': 'fin_fam_02', 'name': 'unauthorized_neft_rtgs', 'style': 'first_person_complaint', 'narratives': ['I woke up to discover two unexplained RTGS transactions totaling 350,000 rupees debited from my current account to an unknown beneficiary in another state. I did not log into netbanking, authorize any transfers, or receive any verification OTP on my registered phone number. My bank branch manager confirmed that the beneficiary was added through an unauthorized netbanking session initiated from an unknown IP address.', 'An unauthorized NEFT transfer of 180,000 rupees was processed from my savings account without my knowledge or approval. No SMS alert or OTP was delivered to my phone during the transaction. Upon inspecting my account statement, I found an unknown individual added as an approved payee just thirty minutes before the funds were transferred.', 'Filing a cybercrime complaint regarding an unauthorized fund transfer. A sum of 220,000 rupees was transferred from my business bank account via IMPS in four rapid installments of 55,000 rupees each. I did not initiate these transfers, nor did I disclose my login credentials or authorization tokens to anyone.', 'An unexplained wire transfer of 145,000 rupees was debited from my account to a beneficiary named Rajesh Enterprise. I have no business association with this entity and did not authorize the transaction. The bank logs indicate that the transfer was executed using an unauthorized netbanking session.', 'I am lodging an urgent complaint for an unauthorized RTGS transfer of 400,000 rupees from my savings balance. The transaction occurred during working hours without any two-factor verification request on my phone. The funds were routed to a private bank account in an unfamiliar location.', 'My bank balance was reduced by 125,000 rupees through an unauthorized NEFT debit. I received an email confirmation after the transaction was already completed, but no authorization OTP was ever received on my mobile device.', 'Unauthorized online transfers totaling 260,000 rupees were executed from my corporate account across two days. The beneficiary accounts were added without my authorization, and the funds were rapidly disbursed to mule accounts.', 'A sudden deduction of 195,000 rupees occurred on my bank account through an unauthorized electronic fund transfer. The transaction was carried out without my consent while I was traveling without internet access.', 'I noticed an unauthorized IMPS deduction of 90,000 rupees on my bank passbook. No transaction alert had been delivered to my registered telephone number when the transfer was executed.', 'Unauthorized electronic fund transfers amounting to 310,000 rupees drained my business account overnight. Unknown beneficiaries were configured and paid without my authorization or token approval.', 'An unauthorized wire transfer of 160,000 rupees was cleared from my savings account to a third-party account without any OTP or security confirmation sent to my mobile.', 'My bank account was debited for 210,000 rupees via unauthorized NEFT transfer without my consent, leaving my operating balance severely depleted.'], 'concise': ['Unauthorized RTGS transfer of 350000 rupees debited from my account without any OTP or consent.', 'Unexplained electronic fund transfer drained 180000 rupees to an unknown beneficiary account.', 'Multiple unauthorized IMPS transactions totaling 220000 rupees executed without my authorization or knowledge.']}, {'id': 'fin_fam_03', 'name': 'pos_double_swipe', 'style': 'first_person_complaint', 'narratives': ['While paying for dinner at a local restaurant, the merchant claimed that the POS machine failed on the first swipe and requested me to enter my card and PIN a second time. Upon checking my online banking statement the next morning, I observed two identical debits of 14,500 rupees charged within sixty seconds of each other. The restaurant management refuses to refund the duplicate debit, claiming only one payment was credited to their account.', 'I made a card purchase of 22,000 rupees at an electronics store where the cashier swiped my credit card twice, stating the first transaction had timed out. My credit card billing statement reflects duplicate charges for the exact same amount at the same merchant terminal.', 'Filing a complaint regarding fraudulent double debit at a merchant point-of-sale terminal. I swiped my debit card for 18,000 rupees, but two identical charges were debited from my bank balance. The merchant refuses to issue a chargeback, claiming the machine threw a network error.', 'An unauthorized duplicate charge of 31,000 rupees appeared on my credit card statement following a purchase at a jewellery store. The cashier claimed the initial transaction had declined and swiped the card a second time, resulting in double billing.', 'My bank account was debited twice for 16,500 rupees within thirty seconds at a retail clothing store. The sales counter operator claimed the first attempt failed, but both transactions cleared successfully against my balance.', 'I was charged double for a hotel booking invoice of 28,000 rupees. The front desk attendant swiped my card on two separate point-of-sale terminals, claiming connectivity issues, but both charges were settled.', 'A merchant swiped my debit card twice for an appliance purchase of 19,000 rupees. Both charges were deducted from my savings account, and the store refuses to assist with reversal.', 'Two identical debits of 24,000 rupees were posted to my credit card account within one minute at an automotive repair workshop after the technician insisted the first swipe had failed.', 'Duplicate transactions of 12,000 rupees each were processed at a supermarket checkout terminal when the cashier swiped my debit card twice, citing machine error.', 'My bank balance shows twin deductions of 26,000 rupees from a single store transaction where the merchant swiped my card multiple times.', 'A retail store processed duplicate charges of 15,000 rupees on my credit card, claiming the first attempt was declined by the network.', 'Two identical POS debits of 35,000 rupees appeared on my account statement after the merchant swiped my card twice during a single retail purchase.'], 'concise': ['Merchant swiped my card twice claiming machine error, resulting in duplicate debits of 14500 rupees.', 'Retail POS terminal processed double charges for the same purchase, and merchant refuses to refund.', 'Duplicate point-of-sale transaction deducted twice from my account after cashier insisted first attempt failed.']}, {'id': 'fin_fam_04', 'name': 'credit_card_auto_debit', 'style': 'first_person_complaint', 'narratives': ['My credit card was charged with seven consecutive unauthorized international transactions in foreign currency totaling 94,000 rupees over the weekend. The charges originated from online merchant platforms located in the United Kingdom and Singapore that I have never visited or heard of. My card was never enrolled in international online transactions, and no OTP was requested by the payment gateway.', 'I discovered unauthorized foreign currency debits amounting to 78,000 rupees on my monthly credit card statement. The transactions were processed through an unfamiliar online gaming service in another country without any two-factor verification on my registered phone.', 'Filing a grievance regarding recurring unauthorized international debits on my credit card. Four separate transactions totaling 56,000 rupees were processed in US dollars without any one-time password prompt. I immediately requested the bank to block the card.', 'My credit card was subjected to unauthorized online transactions amounting to 82,000 rupees from an overseas streaming subscription service. I have never authorized international recurring payments on this credit account.', 'Multiple unauthorized foreign currency charges totaling 65,000 rupees were debited from my credit card limit. The transactions occurred during the early morning hours without any security verification alert.', 'I noticed five unauthorized online debits on my credit card totaling 43,000 rupees billed in Euros. The charges were posted by an unknown digital retailer abroad without my knowledge.', 'An unauthorized overseas transaction of 51,000 rupees was charged to my credit card while I was in my home country. The transaction bypassed two-factor authentication because it was routed internationally.', 'My credit card statement reflects unauthorized international merchant debits amounting to 72,000 rupees. I did not authorize any cross-border transactions on this card.', 'Unauthorized recurring debits totaling 38,000 rupees occurred on my credit card from a foreign digital services company without any SMS authorization code sent to me.', 'Six unauthorized international transactions totaling 60,000 rupees were billed to my credit card from an overseas travel agency platform.', 'My credit card limit was drained by 88,000 rupees through unauthorized international online payments that did not require OTP validation.', 'I am reporting unauthorized foreign currency charges of 47,000 rupees on my credit card that occurred while the physical card was in my possession.'], 'concise': ['Unauthorized international transactions totaling 94000 rupees charged to my credit card without OTP.', 'Credit card was debited multiple times by unknown foreign merchants without two-factor authentication.', 'Foreign currency charges totaling 78000 rupees appeared on my credit card statement without my authorization.']}, {'id': 'fin_fam_05', 'name': 'fake_loan_processing_fee', 'style': 'first_person_complaint', 'narratives': ['I applied for an instant personal loan on a mobile application and received a call from a representative claiming to be a loan officer with a licensed finance company. The representative approved a 500,000-rupee loan subject to payment of an upfront documentation and processing fee of 28,000 rupees. After I transferred the fee via bank transfer, the caller demanded an additional 35,000 rupees for loan insurance. The loan was never disbursed, and the caller blocked my phone number.', 'A caller offering an instant business loan of 1,000,000 rupees instructed me to pay a 45,000-rupee file clearance charge to an individual bank account. I paid the amount through IMPS expecting disbursement within 24 hours. The caller then demanded further payments for GST clearance and ceased all communication.', 'Filing a complaint regarding a fraudulent loan approval scheme. I was offered a low-interest education loan and instructed to pay a 32,000-rupee verification fee. After transferring the money, the fraudsters fabricated a fake sanction letter and demanded more money without releasing the loan.', 'I was deceived into paying 24,000 rupees as an upfront administrative charge for a personal loan promised by an online agent. Once the fee was transferred, the agent disconnected their phone and deleted their messaging profile.', 'A fraudulent loan app promised an instant disbursement of 300,000 rupees upon payment of a 19,000-rupee processing surcharge. After I made the payment via UPI, no funds were credited, and customer support numbers went unanswered.', 'I transferred 36,000 rupees towards mandatory loan insurance after an online finance agent promised a home renovation loan. The agent disappeared after receiving the funds and provided fake bank deposit slips.', 'An individual claiming to be a loan executive demanded 22,000 rupees as upfront stamp duty for a vehicle loan. I paid the sum through netbanking, but the loan was never processed or disbursed.', 'A fraudulent lending website instructed me to pay a 40,000-rupee credit guarantee fee before releasing my approved loan amount. After sending the payment, the operators demanded further deposits and refused refunds.', 'I paid 27,000 rupees as a file processing fee for an emergency personal loan. The agent promised immediate disbursement but stopped answering my calls as soon as the funds were transferred.', 'A fake loan consultant took 33,000 rupees from me as an upfront legal clearance fee for a commercial loan. The consultant vanished and provided forged sanction documents.', 'I was tricked into transferring 21,000 rupees for loan file registration on a fraudulent financial website, but received no loan disbursement.', 'An online loan fraudster collected 48,000 rupees across two installments claiming it was for loan insurance and tax clearance, but failed to disburse the promised loan.'], 'concise': ['Transferred 28000 rupees processing fee for an approved personal loan that was never disbursed.', 'Fraudulent loan agent demanded upfront insurance fees of 45000 rupees and vanished without releasing funds.', 'Paid upfront administrative charges for a promised loan, but the scammer blocked my calls and kept the money.']}, {'id': 'fin_fam_06', 'name': 'work_from_home_task_scam', 'style': 'first_person_complaint', 'narratives': ['I was contacted via WhatsApp with an offer for a part-time job rating hotels and liking YouTube videos for a guaranteed daily income. The group administrator on Telegram initially paid me 1,200 rupees for completing simple evaluation tasks. They then instructed me to invest in prepaid merchant recharge tasks to earn 40 percent profits. I transferred 120,000 rupees across five bank transfers, but when I attempted to withdraw my earnings, the administrator demanded another 80,000 rupees in tax and blocked me.', 'A work-from-home employment scam targeted me through a messaging app offering payment for reviewing products on an e-commerce platform. After paying small initial returns, the organizers convinced me to invest 85,000 rupees in high-yield merchant tasks. All withdrawal options were locked, and the operators demanded more money.', 'Filing a cyber complaint against a Telegram task investment scam. I was persuaded to complete digital marketing tasks requiring advance deposits. I transferred 160,000 rupees into various individual bank accounts, but the platform refused all withdrawal requests, citing account audit requirements.', 'I was deceived into investing 95,000 rupees in a remote rating job scheme. The organizers showed a fictitious balance on an online dashboard but refused to release my principal or promised profits unless I deposited additional funds.', 'A part-time online job group promised daily returns for reviewing movie trailers. After gaining my trust with small payouts, they induced me to deposit 75,000 rupees in premium task packages, after which all communication stopped.', 'I lost 140,000 rupees to a fraudulent task investment portal. The operators instructed me to send funds to multiple bank accounts to unlock commissions, but completely blocked my access once the transfers were completed.', 'A remote job recruitment scheme lured me into paying 60,000 rupees across several merchant recharge tasks. The administrators refused to release my earnings, claiming I made an error during task completion.', 'I transferred 110,000 rupees to an online task platform promising 30 percent daily interest for completing survey tasks. The organizers froze my account and demanded additional verification deposits.', 'A fraudulent work-from-home program took 80,000 rupees from me under the guise of security deposits for freelance data evaluation tasks. The promised returns were never delivered.', 'I was tricked into depositing 135,000 rupees into an online task portal. The administrators claimed that my funds were locked until I completed an impossible final task requiring more money.', 'An online job scam induced me to transfer 50,000 rupees for promotional rating tasks, but locked my account when I requested a withdrawal.', 'I lost 105,000 rupees to a Telegram part-time job scheme that promised high returns for prepaid online merchant tasks.'], 'concise': ['Lost 120000 rupees to a Telegram work-from-home task scam that promised high profits for prepaid tasks.', 'Paid advance deposits for an online rating job, but the operators froze my funds and demanded more money.', 'Part-time job investment scheme took 85000 rupees in task deposits and blocked all withdrawal requests.']}, {'id': 'fin_fam_07', 'name': 'pension_pf_withdrawal_scam', 'style': 'first_person_complaint', 'narratives': ['A caller claiming to be an officer with the Employees Provident Fund Organisation contacted me regarding my pending pension withdrawal claim. The caller stated that my pension funds of 450,000 rupees were held up due to an administrative discrepancy and required an upfront processing fee of 32,000 rupees. I transferred the money to the specified account. The caller subsequently demanded additional funds for tax clearance, and no pension was ever credited.', 'I received a call from an individual impersonating a pension disbursement official who promised to expedite my provident fund settlement. The individual instructed me to pay a 25,000-rupee file clearance charge via UPI. Once the payment was made, the caller disconnected the phone and could not be reached.', 'Filing a cyber complaint regarding a provident fund withdrawal fraud. A fraudster posing as an EPFO commissioner assured me that my accumulated PF balance would be deposited within two hours upon paying an 18,000-rupee administrative surcharge. The claim was entirely fraudulent, and my money was stolen.', 'A caller claiming to represent the state pension department demanded a 40,000-rupee audit verification fee to release my retirement gratuity. I transferred the funds through netbanking, but the individual disappeared after receiving the payment.', 'I was defrauded of 28,000 rupees by a scammer who claimed to be a pension clearance officer. The caller claimed my pension records had a tax shortfall that required immediate online settlement.', 'An individual contacted my elderly father claiming his monthly pension was blocked and demanded a 22,000-rupee biometric update fee. After the money was transferred, the family realized it was a financial scam.', 'A fraudulent EPFO consultant took 35,000 rupees from me as an upfront fee to resolve a pension transfer claim. The consultant provided forged receipts and terminated all contact.', 'I paid 30,000 rupees to a caller who promised to release my frozen provident fund balance. The caller was an imposter, and the funds were transferred to a fraudulent bank account.', 'A scammer impersonating a government pension auditor demanded a 26,000-rupee processing surcharge to clear my pension arrears. The money was stolen, and no pension was released.', 'I was tricked into transferring 42,000 rupees to an individual claiming to be an EPFO zonal officer assisting with an urgent retirement claim.', 'A caller posing as a pension officer collected 20,000 rupees as a document verification fee and ceased all communication.', 'Fraudsters took 38,000 rupees from me under the false promise of clearing an overdue provident fund transfer.'], 'concise': ['Caller impersonating an EPFO officer took 32000 rupees upfront processing fee for pension release.', 'Paid advance fee to a fake pension consultant who promised to expedite provident fund settlement.', 'Scammer posing as a pension department official defrauded me of 25000 rupees via UPI transfer.']}, {'id': 'fin_fam_08', 'name': 'insurance_policy_bonus', 'style': 'first_person_complaint', 'narratives': ['I was contacted by a caller claiming to represent the Insurance Regulatory and Development Authority who informed me that an unpaid bonus of 380,000 rupees had accumulated on an old insurance policy. The caller instructed me to transfer an administrative fee of 36,000 rupees to release the funds. After making the payment via IMPS, the caller demanded an additional 45,000 rupees for tax deduction, and no bonus was ever released.', 'A caller claiming to be a senior executive with an insurance corporation promised to release lapsed insurance maturity benefits if I paid an activation fee of 28,000 rupees. I paid the amount, but the caller demanded further deposits and refused to provide documentation.', 'Filing a complaint regarding an insurance bonus fraud. A scammer contacted me stating that my life insurance policy had earned an unclaimed dividend of 250,000 rupees. They instructed me to deposit 22,000 rupees into a verification account, which was subsequently stolen.', 'I was defrauded of 48,000 rupees by an individual claiming to represent an insurance grievance redressal cell. The individual promised to recover money from a surrendered policy upon payment of legal clearance fees.', 'A caller claiming to be an insurance ombudsman informed me of an accrued policy bonus. I transferred 30,000 rupees as processing fees, after which the caller disconnected their phone and blocked my number.', 'I paid 42,000 rupees towards tax clearance after a caller promised the immediate release of an overdue insurance policy settlement. The promised funds were fictitious, and my money was lost.', 'A fraudulent insurance agent convinced me to pay 25,000 rupees to reactivate a lapsed life insurance plan and receive an accumulated bonus. The agent disappeared after receiving the funds.', 'An individual impersonating an insurance company manager took 35,000 rupees from me as an upfront verification charge for a policy bonus release.', 'I transferred 27,000 rupees to a fraudster who promised to disburse accumulated dividends on my insurance policy. No funds were ever received.', 'A caller took 50,000 rupees across two installments claiming it was for regulatory approval of an insurance bonus payout.', 'I was deceived into paying 20,000 rupees as an administrative charge to release an insurance policy bonus that did not exist.', 'Fraudulent callers posing as insurance executives stole 38,000 rupees from me by promising a release of accumulated policy dividends.'], 'concise': ['Caller promising accrued insurance policy bonus defrauded me of 36000 rupees in upfront fees.', 'Paid advance fees to a fake insurance executive who promised to release lapsed policy dividends.', 'Fraudulent insurance agent promised 380000 rupees bonus and stole 28000 rupees in processing charges.']}, {'id': 'fin_fam_09', 'name': 'credit_limit_upgrade', 'style': 'first_person_complaint', 'narratives': ['A caller claiming to represent my bank credit card department informed me that my card was pre-approved for a credit limit enhancement from 100,000 to 400,000 rupees. The caller asked me to verify my identity by confirming my card number and reading out a six-digit verification code sent to my mobile. Shortly after providing the code, an unauthorized transaction of 64,000 rupees was debited from my credit card limit.', 'I received a call offering a complimentary credit card limit upgrade. The representative requested my card expiry date, CVV, and an authorization OTP to activate the new limit. Within minutes of sharing the code, 48,000 rupees was charged to my card by an online merchant.', 'Filing a complaint regarding a credit card limit increase scam. A caller impersonating a bank customer care executive asked for an OTP to approve my limit enhancement request. The OTP was used to execute an unauthorized transaction of 55,000 rupees.', 'A fraudster offering to upgrade my credit card to platinum status requested my banking details and a security code received on my phone. The code was used to process an unauthorized debit of 38,000 rupees.', 'I was deceived by a caller offering to double my credit card limit. After providing the OTP sent to my mobile, an unauthorized transaction of 72,000 rupees was charged to my card balance.', 'A caller claiming to be from the card services division requested an OTP to complete a credit limit upgrade. Providing the code resulted in an unauthorized purchase of 42,000 rupees.', 'An unauthorized credit card debit of 50,000 rupees occurred after a caller tricked me into sharing an authorization code under the pretext of upgrading my credit limit.', 'A scammer offering a credit limit hike requested my card credentials and OTP. Once disclosed, 35,000 rupees was debited from my available credit line.', 'I shared an OTP with a caller who claimed it was required to confirm a credit limit upgrade. The caller used the code to execute an unauthorized wire debit of 60,000 rupees.', 'A caller claiming to represent my bank tricked me into reading out an SMS code for a card upgrade, resulting in a 46,000-rupee unauthorized transaction.', 'I lost 30,000 rupees on my credit card after sharing an authorization code with a caller promising a credit limit enhancement.', 'An unauthorized transaction of 58,000 rupees was executed on my credit card after a caller deceived me into revealing an OTP for a card limit upgrade.'], 'concise': ['Caller offering credit card limit upgrade tricked me into sharing an OTP and debited 64000 rupees.', 'Shared authorization code for a promised credit limit enhancement, resulting in unauthorized card transaction.', 'Scammer impersonating bank card department stole 48000 rupees by requesting an OTP for a limit hike.']}]

def get_samples():
    samples = []
    for fam in FAMILIES:
        for text in fam['narratives']:
            samples.append({
                'text': text,
                'is_narrative': True,
                'scenario_family': fam['name'],
                'lineage_id': fam['id'],
                'narrative_style': fam['style'],
                'word_count': len(text.split())
            })
        for text in fam['concise']:
            samples.append({
                'text': text,
                'is_narrative': False,
                'scenario_family': fam['name'],
                'lineage_id': fam['id'],
                'narrative_style': 'concise_report',
                'word_count': len(text.split())
            })
    return samples

def get_narratives():
    res = []
    for fam in FAMILIES:
        res.extend(fam['narratives'])
    return res

def get_concise():
    res = []
    for fam in FAMILIES:
        res.extend(fam['concise'])
    return res
